import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { DatabaseSync } from 'node:sqlite';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = path.dirname(fileURLToPath(import.meta.url));
const dbPath = process.env.DB_PATH || path.join(root, 'data', 'workboard.sqlite');
if (dbPath !== ':memory:') {
  const { mkdir } = await import('node:fs/promises');
  await mkdir(path.dirname(path.resolve(dbPath)), { recursive: true });
}
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, title TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0)`);
// Upgrade databases created by earlier checkpoints.
if (!db.prepare("PRAGMA table_info(projects)").all().some(column => column.name === 'archived')) db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0');
const listProjects = db.prepare(`SELECT p.id, p.name, p.archived, COUNT(t.id) AS totalCount,
  COALESCE(SUM(t.completed), 0) AS completedCount FROM projects p LEFT JOIN tasks t ON t.project_id=p.id
  WHERE p.archived=? GROUP BY p.id ORDER BY p.id`);
const getProject = db.prepare('SELECT id, name, archived FROM projects WHERE id = ?');
const addProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
const renameProject = db.prepare('UPDATE projects SET name=? WHERE id=?');
const setArchived = db.prepare('UPDATE projects SET archived=? WHERE id=?');
const listTasks = db.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const getTask = db.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE id = ? AND project_id = ?');
const addTask = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');

const server = createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  const send = (status, body, type = 'application/json; charset=utf-8') => {
    res.writeHead(status, { 'Content-Type': type, 'Cache-Control': 'no-store' });
    res.end(body);
  };
  const readBody = async () => { let raw = ''; for await (const chunk of req) raw += chunk; return JSON.parse(raw); };
  if (url.pathname === '/health' && req.method === 'GET') return send(200, JSON.stringify({ status: 'ok' }));
  if (url.pathname === '/api/projects' && req.method === 'GET') return send(200, JSON.stringify(listProjects.all(url.searchParams.get('filter') === 'archived' ? 1 : 0)));
  if (url.pathname === '/api/projects' && req.method === 'POST') {
    try {
      const name = String((await readBody()).name ?? '').trim();
      if (!name) return send(400, JSON.stringify({ error: 'Project name is required' }));
      const result = addProject.run(name);
      return send(201, JSON.stringify(getProject.get(Number(result.lastInsertRowid))));
    } catch { return send(400, JSON.stringify({ error: 'Invalid request' })); }
  }
  const renameRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/rename$/);
  if (renameRoute && req.method === 'POST') {
    const project = getProject.get(Number(renameRoute[1]));
    if (!project) return send(404, JSON.stringify({ error: 'Not found' }));
    if (project.archived) return send(409, JSON.stringify({ error: 'Archived project' }));
    try {
      const name = String((await readBody()).name ?? '').trim();
      if (!name) return send(400, JSON.stringify({ error: 'Project name is required' }));
      renameProject.run(name, project.id);
      return send(200, JSON.stringify(getProject.get(project.id)));
    } catch { return send(400, JSON.stringify({ error: 'Invalid request' })); }
  }
  const archiveRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/(archive|restore)$/);
  if (archiveRoute && req.method === 'POST') {
    const project = getProject.get(Number(archiveRoute[1]));
    if (!project) return send(404, JSON.stringify({ error: 'Not found' }));
    setArchived.run(archiveRoute[2] === 'archive' ? 1 : 0, project.id);
    return send(200, JSON.stringify(getProject.get(project.id)));
  }
  const taskRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
  if (taskRoute) {
    const projectId = Number(taskRoute[1]);
    const project = getProject.get(projectId);
    if (!project) return send(404, JSON.stringify({ error: 'Not found' }));
    if (!taskRoute[2] && req.method === 'GET') return send(200, JSON.stringify(listTasks.all(projectId)));
    try {
      const body = await readBody();
      if (!taskRoute[2] && req.method === 'POST') {
        if (project.archived) return send(409, JSON.stringify({ error: 'Archived project' }));
        const title = String(body.title ?? '').trim();
        if (!title) return send(400, JSON.stringify({ error: 'Task title is required' }));
        const result = addTask.run(projectId, title);
        return send(201, JSON.stringify(getTask.get(Number(result.lastInsertRowid), projectId)));
      }
      if (taskRoute[2] && req.method === 'PATCH') {
        if (project.archived) return send(409, JSON.stringify({ error: 'Archived project' }));
        updateTask.run(body.completed ? 1 : 0, Number(taskRoute[2]), projectId);
        const task = getTask.get(Number(taskRoute[2]), projectId);
        return task ? send(200, JSON.stringify(task)) : send(404, JSON.stringify({ error: 'Not found' }));
      }
      return send(405, JSON.stringify({ error: 'Method not allowed' }));
    } catch { return send(400, JSON.stringify({ error: 'Invalid request' })); }
  }
  if (url.pathname.startsWith('/api/projects/') && req.method === 'GET') {
    const project = getProject.get(Number(url.pathname.split('/').at(-1)));
    return project ? send(200, JSON.stringify(project)) : send(404, JSON.stringify({ error: 'Not found' }));
  }
  if (req.method === 'GET' && (url.pathname === '/' || /^\/projects\/\d+\/?$/.test(url.pathname))) {
    try { return send(200, await readFile(path.join(root, 'public', 'index.html')), 'text/html; charset=utf-8'); }
    catch { return send(500, 'Application unavailable', 'text/plain; charset=utf-8'); }
  }
  if (req.method === 'GET' && ['/app.js', '/style.css'].includes(url.pathname)) {
    try {
      const file = url.pathname.slice(1);
      return send(200, await readFile(path.join(root, 'public', file)), file.endsWith('.js') ? 'text/javascript; charset=utf-8' : 'text/css; charset=utf-8');
    } catch { return send(404, 'Not found', 'text/plain; charset=utf-8'); }
  }
  send(404, JSON.stringify({ error: 'Not found' }));
});

const port = Number(process.env.PORT || 8080);
server.listen(port, '0.0.0.0');

const app = document.querySelector('#app');

function element(tag, attributes = {}, text = '') {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(attributes)) node.setAttribute(key, value);
  if (text) node.textContent = text;
  return node;
}

async function render() {
  app.replaceChildren();
  const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
  if (match) {
    const response = await fetch(`/api/projects/${match[1]}`);
    if (!response.ok) {
      app.append(element('h1', {}, 'Project not found'));
      const back = element('button', { type: 'button' }, 'Projects');
      back.addEventListener('click', () => { location.href = '/'; });
      app.append(back);
      return;
    }
    const project = await response.json();
    app.append(element('h1', {}, project.name));
    const back = element('button', { type: 'button' }, 'Projects');
    back.addEventListener('click', () => { location.href = '/'; });
    app.append(back);
    if (project.archived) app.append(element('p', {}, 'Archived project'));

    const renameForm = element('form');
    const renameLabel = element('label', { for: 'new-project-name' }, 'New project name');
    const renameInput = element('input', { id: 'new-project-name', type: 'text' });
    const renameButton = element('button', { type: 'submit' }, 'Rename project');
    const renameAlert = element('p', { role: 'alert', 'aria-live': 'assertive', hidden: '' });
    if (project.archived) { renameInput.disabled = true; renameButton.disabled = true; }
    renameForm.append(renameLabel, renameInput, renameButton);
    app.append(renameForm, renameAlert);
    renameForm.addEventListener('submit', async event => {
      event.preventDefault();
      const name = renameInput.value.trim();
      if (!name) { renameAlert.textContent = 'Project name is required'; renameAlert.hidden = false; renameInput.focus(); return; }
      const response = await fetch(`/api/projects/${match[1]}/rename`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }) });
      if (response.ok) render();
    });

    const form = element('form');
    const label = element('label', { for: 'task-title' }, 'Task title');
    const input = element('input', { id: 'task-title', name: 'title', type: 'text' });
    const create = element('button', { type: 'submit' }, 'Create task');
    const alert = element('p', { role: 'alert', 'aria-live': 'assertive', hidden: '' });
    if (project.archived) { input.disabled = true; create.disabled = true; }
    form.append(label, input, create);
    app.append(form, alert);
    const filterLabel = element('label', { for: 'task-filter' }, 'Task filter');
    const filter = element('select', { id: 'task-filter' });
    for (const value of ['All', 'Open', 'Completed']) filter.append(element('option', { value: value.toLowerCase() }, value));
    app.append(filterLabel, filter);
    const list = element('section', { 'aria-label': 'Tasks' });
    app.append(list);
    async function loadTasks() {
      const tasks = await (await fetch(`/api/projects/${match[1]}/tasks`)).json();
      list.replaceChildren();
      for (const task of tasks) {
        if (filter.value === 'open' && task.completed || filter.value === 'completed' && !task.completed) continue;
        const row = element('div', { 'data-testid': 'task-row', class: 'task-row' });
        row.append(element('span', {}, task.title));
        const checkbox = element('input', { type: 'checkbox', 'aria-label': `Complete ${task.title}` });
        checkbox.checked = Boolean(task.completed);
        checkbox.disabled = Boolean(project.archived);
        checkbox.addEventListener('change', async () => {
          await fetch(`/api/projects/${match[1]}/tasks/${task.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
          await loadTasks();
        });
        row.append(checkbox);
        list.append(row);
      }
    }
    filter.addEventListener('change', loadTasks);
    form.addEventListener('submit', async event => {
      event.preventDefault();
      const title = input.value.trim();
      if (!title) { alert.textContent = 'Task title is required'; alert.hidden = false; input.focus(); return; }
      const result = await fetch(`/api/projects/${match[1]}/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }) });
      if (result.ok) { input.value = ''; alert.textContent = ''; alert.hidden = true; await loadTasks(); }
    });
    await loadTasks();
    return;
  }

  app.append(element('h1', {}, 'Workboard'));
  const filterLabel = element('label', { for: 'project-filter' }, 'Project filter');
  const filter = element('select', { id: 'project-filter' });
  filter.append(element('option', { value: 'active' }, 'Active'), element('option', { value: 'archived' }, 'Archived'));
  app.append(filterLabel, filter);
  const form = element('form');
  const label = element('label', { for: 'project-name' }, 'Project name');
  const input = element('input', { id: 'project-name', name: 'name', type: 'text' });
  const create = element('button', { type: 'submit' }, 'Create project');
  const alert = element('p', { role: 'alert', 'aria-live': 'assertive', hidden: '' });
  form.append(label, input, create);
  app.append(form, alert);
  const list = element('section', { 'aria-label': 'Projects' });
  app.append(list);

  async function loadProjects() {
    const projects = await (await fetch(`/api/projects?filter=${filter.value}`)).json();
    list.replaceChildren();
    for (const project of projects) {
      const row = element('div', { 'data-testid': 'project-row', class: 'project-row' });
      row.append(element('span', {}, project.name));
      row.append(element('span', { 'data-testid': 'project-summary' }, `${project.completedCount}/${project.totalCount} completed`));
      const open = element('button', { type: 'button' }, 'Open project');
      open.addEventListener('click', () => { location.href = `/projects/${project.id}`; });
      row.append(open);
      const action = element('button', { type: 'button' }, filter.value === 'active' ? 'Archive project' : 'Restore project');
      action.addEventListener('click', async () => {
        await fetch(`/api/projects/${project.id}/${filter.value === 'active' ? 'archive' : 'restore'}`, { method: 'POST' });
        await loadProjects();
      });
      row.append(action);
      list.append(row);
    }
  }
  filter.addEventListener('change', loadProjects);
  form.addEventListener('submit', async event => {
    event.preventDefault();
    const name = input.value.trim();
    if (!name) { alert.textContent = 'Project name is required'; alert.hidden = false; input.focus(); return; }
    const response = await fetch('/api/projects', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }) });
    if (response.ok) { input.value = ''; alert.textContent = ''; alert.hidden = true; await loadProjects(); }
  });
  await loadProjects();
}

render();

